const listUsers = `-- name: ListUsers :many
SELECT
    id,
    display_name,
    email,
    role,
    region_id,
    district_id,
    school_id,
    is_super_admin,
    last_login_at
FROM
    users
WHERE
    deleted_at IS NULL
ORDER BY
    role
`

type ListUsersRow struct {
	ID           int32
	DisplayName  string
	Email        string
	Role         string
	RegionID     sql.NullInt32
	DistrictID   sql.NullInt32
	SchoolID     sql.NullInt32
	IsSuperAdmin sql.NullBool
	LastLoginAt  sql.NullTime
}

func (q *Queries) ListUsers(ctx context.Context) ([]ListUsersRow, error) {
	rows, err := q.db.QueryContext(ctx, listUsers)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListUsersRow
	for rows.Next() {
		var i ListUsersRow
		if err := rows.Scan(
			&i.ID,
			&i.DisplayName,
			&i.Email,
			&i.Role,
			&i.RegionID,
			&i.DistrictID,
			&i.SchoolID,
			&i.IsSuperAdmin,
			&i.LastLoginAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

